/// A character's strokes; a capital or small letter not drawn borrows the other case.
pub fn glyph(c: char) -> Option<&'static [[u8; 4]]> {
	let find = |c: char| GLYPHS.binary_search_by_key(&c, |g| g.0).ok().map(|k| GLYPHS[k].1);
	find(c).or_else(|| {
		let other: String = if c.is_lowercase() { c.to_uppercase().collect() } else { c.to_lowercase().collect() };
		other.chars().next().filter(|&o| o != c).and_then(find)
	})
}

/// How far across (in grid points) to move a glyph so the middle of what it draws is the
/// cell's middle.
pub fn shift(strokes: &[[u8; 4]]) -> f32 {
	let (lo, hi) = strokes.iter().fold((u8::MAX, u8::MIN), |(lo, hi), s| (lo.min(s[0]).min(s[2]), hi.max(s[0]).max(s[2])));
	COLS / 2.0 - (lo as f32 + hi as f32) / 2.0
}
